export const handler = awslambda.streamifyResponse(async (event, responseStream) => {
  const out = await bedrock.send(new ConverseStreamCommand({ modelId, messages, inferenceConfig: { maxTokens: 512 } }));
  for await (const chunk of out.stream!) {
    const text = chunk.contentBlockDelta?.delta?.text;
    if (text) responseStream.write(text); // the caller sees this now, not at the end
  }
  responseStream.end();
});

const integration = new apigateway.LambdaIntegration(answerFn, {
  responseTransferMode: apigateway.ResponseTransferMode.STREAM,
});

