function compact(turns) {
  const head = turns[0];            // the instruction — kept verbatim
  const tail = turns.slice(-2);     // the latest turns — kept verbatim
  const middle = summarize(turns.slice(1, -2)); // the middle — summarized
  return [head, middle, ...tail];
}

